1	#!/usr/bin/env node
2	/**
3	 * source-dupes.mjs — gate `source-dupes` (contract `kumitate-source-dupes-v1`, round 56).
4	 *
5	 * The SOURCES duplicate-URL ratchet. The maintained census
6	 * (`scripts/sources-census.sh validate`) prints a W04 warning when two Registry
7	 * rows carry the same normalized URL under different scopes; it never fails
8	 * (warnings do not gate). Those warnings are the lane's own taste evidence
9	 * drifting — the same source admitted twice under different scopes splits
10	 * which row is authoritative and which `used-by` path owns the citation.
11	 * This gate promotes the warning class into a pinned, scored contract: the set
12	 * of live duplicate groups must equal the pinned `known` set — a NEW duplicate
13	 * is a regression (DRIFT), and a `known` entry that no longer duplicates is a
14	 * stale pin (DRIFT too: resolve it — supersede or re-anchor a row — and remove
15	 * the pin; silence is not a fix).
16	 *
17	 *   node scripts/source-dupes.mjs [--registry <path>] [--sources <path>]
18	 *   node scripts/source-dupes.mjs --selftest
19	 *
20	 * Verdicts (one line on stdout, after optional per-item notes):
21	 *   SOURCE_DUPES: CLEAN groups=<n> known=<n>       exit 0
22	 *   SOURCE_DUPES: DRIFT groups=<n> known=<m> bad=<k> first=<item>   exit 1
23	 *   SOURCE_DUPES: FAIL-CLOSED reason=<why>         exit 2 (could not evaluate)
24	 *   SOURCE_DUPES: USAGE ...                        exit 64
25	 *
26	 * Registry (default `.ufo/pins/source-dupes.json`, lane-root-relative):
27	 *   { "version": 1,
28	 *     "known": [ { "ids": ["S034","S050"], "url": "<normalized-url>", "why": "<reason>" }, ... ] }
29	 *
30	 * A `known` entry names the full member set of one duplicate group by row id
31	 * and its normalized URL — the census-normalized form (scheme and trailing
32	 * `/` stripped, `#fragment` stripped, host lowercased; the SAME normalization
33	 * the maintained census applies before printing W04).
34	 *
35	 * Duplicate semantics (identical to `sources-census.sh` W04): two rows share a
36	 * normalized URL AND differ in their `scope` cell. Same-URL + same-scope is
37	 * the census's E04 family, not this gate's; rows with no URL at all never form
38	 * a group; a lone row is never a group. The census tolerates same-URL /
39	 * different-scope as a warning — this gate makes the TOLERANCE explicit: only
40	 * the pinned groups may exist.
41	 *
42	 * Rules:
43	 *   - the live duplicate-group set is computed from `corpus/SOURCES.md` over
44	 *     the Registry section only (0–3 leading spaces, `## Registry` … next `#`);
45	 *     the separator row and rows outside Registry are ignored.
46	 *   - DRIFT `new-duplicate:<url>` — a live group not in `known`.
47	 *   - DRIFT `stale-known:<ids>` — a `known` entry whose members no longer form
48	 *     that group (a row was superseded/removed, the url re-anchored, or the
49	 *     scope changed so it is no longer a duplicate).
50	 *   - DRIFT `known-mismatch:<url>` — a `known` entry whose `ids`/`url` do not
51	 *     match the live group it partly covers (members must match exactly).
52	 *   - FAIL-CLOSED (exit 2, never a score): registry unreadable / not JSON /
53	 *     version ≠ 1 / `known` not an array / an entry missing ids+url+why /
54	 *     duplicate `known` entries covering the same row id; sources doc
55	 *     unreadable / no Registry section.
56	 *   - an EMPTY `known` array is legal ONLY when no live group exists; known=0
57	 *     with a live group is DRIFT, known>0 is never vacuous.
58	 *
59	 * The gate never writes. It reads the registry and the sources doc only.
60	 *
61	 * Selftest: hermetic fixtures under mkdtemp, twelve cases, one red-before per
62	 * rule; the final line reads `SOURCE_DUPES_SELFTEST: PASS (12/12)` +
63	 * `VERDICT: PASS`, exit 0.
64	 *
65	 * Exit map: 0 clean · 1 a real defect (drift) · 2 fail-closed · 64 usage.
66	 * Owner: kumitate L1. Row: SKILL.md §Gate registry (`source-dupes`, gate);
67	 * pin: SCORECARD.md `kumitate-gate-pins-v1` (`pin.source-dupes`).
68	 */
69	import { spawnSync } from 'node:child_process';
70	import { lstatSync, mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
71	import { dirname, join, resolve } from 'node:path';
72	import { tmpdir } from 'node:os';
73	import { fileURLToPath } from 'node:url';
74	
75	const SELF = fileURLToPath(import.meta.url);
76	const LANE = resolve(dirname(SELF), '..');
77	const DEFAULT_REGISTRY = '.ufo/pins/source-dupes.json';
78	const DEFAULT_SOURCES = 'corpus/SOURCES.md';
79	const SID = /^S[0-9]{3,}$/;
80	
81	function usage() {
82	  process.stderr.write('SOURCE_DUPES: USAGE node scripts/source-dupes.mjs [--registry <path>] [--sources <path>] | --selftest\n');
83	  process.exit(64);
84	}
85	
86	// Same normalization as scripts/sources-census.sh url_of(): strip scheme,
87	// fragment and one trailing slash; lowercase the host only.
88	function urlOf(sourceCell) {
89	  const m = sourceCell.match(/https?:\/\/[^\s|]+/);
90	  if (!m) return '';
91	  let u = m[0];
92	  u = u.replace(/#[^ ]*$/, '').replace(/\/$/, '').replace(/^[A-Za-z]+:\/\//, '');
93	  const n = u.indexOf('/');
94	  return n ? u.slice(0, n).toLowerCase() + u.slice(n) : u.toLowerCase();
95	}
96	
97	function loadRegistry(regPath) {
98	  let raw;
99	  try {
100	    if (!lstatSync(regPath).isFile()) {
101	      return { ok: false, reason: 'registry not a regular file' };
102	    }
103	    raw = readFileSync(regPath);
104	  } catch (e) {
105	    return { ok: false, reason: `registry unreadable: ${e.code || 'EIO'}` };
106	  }
107	  let doc;
108	  try {
109	    doc = JSON.parse(raw.toString('utf8'));
110	  } catch {
111	    return { ok: false, reason: 'registry not valid JSON' };
112	  }
113	  if (!doc || typeof doc !== 'object' || Array.isArray(doc)) {
114	    return { ok: false, reason: 'registry not an object' };
115	  }
116	  if (doc.version !== 1) {
117	    return { ok: false, reason: `registry version ${JSON.stringify(doc.version)} !== 1` };
118	  }
119	  if (!Array.isArray(doc.known)) {
120	    return { ok: false, reason: 'registry known not an array' };
121	  }
122	  const covered = new Set();
123	  for (const k of doc.known) {
124	    if (!k || typeof k !== 'object' || !Array.isArray(k.ids) || k.ids.length < 2
125	        || k.ids.some((id) => typeof id !== 'string' || !SID.test(id))
126	        || new Set(k.ids).size !== k.ids.length
127	        || typeof k.url !== 'string' || k.url.length === 0
128	        || typeof k.why !== 'string' || k.why.length === 0) {
129	      return { ok: false, reason: 'a known entry lacks valid ids(>=2, unique, S###)/url/why' };
130	    }
131	    for (const id of k.ids) {
132	      if (covered.has(id)) {
133	        return { ok: false, reason: `row id ${JSON.stringify(id)} covered by two known entries` };
134	      }
135	      covered.add(id);
136	    }
137	  }
138	  return { ok: true, known: doc.known };
139	}
140	
141	// Rows in the Registry section only: `## Registry` until the next top heading;
142	// 0–3 leading spaces tolerated, 4+ is indented code (census parser note).
143	function loadRows(srcPath) {
144	  let raw;
145	  try {
146	    if (!lstatSync(srcPath).isFile()) {
147	      return { ok: false, reason: 'sources doc not a regular file' };
148	    }
149	    raw = readFileSync(srcPath, 'utf8');
150	  } catch (e) {
151	    return { ok: false, reason: `sources doc unreadable: ${e.code || 'EIO'}` };
152	  }
153	  const rows = [];
154	  let inRegistry = false;
155	  let seenRegistry = false;
156	  for (const line0 of raw.split('\n')) {
157	    if (/^ {0,3}##[ \t]/.test(line0)) {
158	      const h = line0.replace(/^ {0,3}/, '').replace(/^##[ \t]+/, '').trim();
159	      inRegistry = h === 'Registry';
160	      if (inRegistry) seenRegistry = true;
161	      continue;
162	    }
163	    if (/^ {0,3}#[ \t]/.test(line0)) { inRegistry = false; continue; }
164	    if (!inRegistry || !/^ {0,3}\|/.test(line0)) continue;
165	    const cells = line0.replace(/^ {0,3}/, '').split('|').map((c) => c.trim());
166	    if (cells.length !== 13) continue;                       // NF=13 like the census
167	    if (/^-+$/.test(cells[2].replace(/\s/g, '')) || /^-+$/.test((cells[1] || '').replace(/\s/g, ''))) continue; // separator
168	    const id = cells[1];
169	    if (!SID.test(id)) continue;
170	    rows.push({ id, scope: cells[5], url: urlOf(cells[2]) });
171	  }
172	  if (!seenRegistry) {
173	    return { ok: false, reason: 'sources doc carries no ## Registry section' };
174	  }
175	  if (rows.length === 0) {
176	    return { ok: false, reason: 'sources doc carries no S### rows in Registry' };
177	  }
178	  return { ok: true, rows };
179	}
180	
181	// Live duplicate groups: same normalized URL, differing scope cells (W04).
182	function duplicateGroups(rows) {
183	  const byUrl = new Map();
184	  for (const r of rows) {
185	    if (!r.url) continue;
186	    if (!byUrl.has(r.url)) byUrl.set(r.url, []);
187	    byUrl.get(r.url).push(r);
188	  }
189	  const groups = [];
190	  for (const [url, members] of byUrl) {
191	    if (members.length < 2) continue;
192	    const scopes = new Set(members.map((m) => m.scope));
193	    if (scopes.size < 2) continue;
194	    groups.push({ url, ids: members.map((m) => m.id).sort() });
195	  }
196	  groups.sort((a, b) => a.url.localeCompare(b.url));
197	  return groups;
198	}
199	
200	const key = (ids) => ids.slice().sort().join('+');
201	
202	function evaluate(registryPath, sourcesPath) {
203	  const reg = loadRegistry(registryPath);
204	  if (!reg.ok) {
205	    return { verdict: 'FAIL-CLOSED', reason: reg.reason, exit: 2 };
206	  }
207	  const src = loadRows(sourcesPath);
208	  if (!src.ok) {
209	    return { verdict: 'FAIL-CLOSED', reason: src.reason, exit: 2 };
210	  }
211	  const live = duplicateGroups(src.rows);
212	  const liveByKey = new Map(live.map((g) => [key(g.ids), g]));
213	  const liveByUrl = new Map(live.map((g) => [g.url, g]));
214	  const knownIds = new Map();
215	  const bad = [];
216	  for (const k of reg.known) {
217	    knownIds.set(key(k.ids), k);
218	    const g = liveByKey.get(key(k.ids));
219	    if (!g) {
220	      // Does any live group share this URL or overlap members? Then the pin's
221	      // shape is wrong rather than simply stale.
222	      const overlap = live.find((lg) => lg.ids.some((id) => k.ids.includes(id)));
223	      if (overlap) {
224	        bad.push(`known-mismatch:${k.url} live=${overlap.ids.join(',')}`);
225	      } else if (liveByUrl.has(k.url)) {
226	        bad.push(`known-mismatch:${k.url} live=${liveByUrl.get(k.url).ids.join(',')}`);
227	      } else {
228	        bad.push(`stale-known:${k.ids.join(',')}`);
229	      }
230	    } else if (g.url !== k.url) {
231	      bad.push(`known-mismatch:${k.url} live-url=${g.url}`);
232	    }
233	  }
234	  for (const g of live) {
235	    if (!knownIds.has(key(g.ids))) {
236	      bad.push(`new-duplicate:${g.url} ids=${g.ids.join(',')}`);
237	    }
238	  }
239	  if (bad.length > 0) {
240	    return { verdict: 'DRIFT', groups: live.length, known: reg.known.length, bad, exit: 1 };
241	  }
242	  return { verdict: 'CLEAN', groups: live.length, known: reg.known.length, exit: 0 };
243	}
244	
245	function emit(result) {
246	  if (result.verdict === 'CLEAN') {
247	    process.stdout.write(`SOURCE_DUPES: CLEAN groups=${result.groups} known=${result.known}\n`);
248	  } else if (result.verdict === 'DRIFT') {
249	    for (const b of result.bad.slice(1)) process.stdout.write(`SOURCE_DUPES: note ${b}\n`);
250	    process.stdout.write(`SOURCE_DUPES: DRIFT groups=${result.groups} known=${result.known} bad=${result.bad.length} first=${result.bad[0]}\n`);
251	  } else {
252	    process.stdout.write(`SOURCE_DUPES: FAIL-CLOSED reason=${result.reason}\n`);
253	  }
254	  process.exit(result.exit);
255	}
256	
257	function selftest() {
258	  const root = mkdtempSync(join(tmpdir(), 'source-dupes-st.'));
259	  const results = [];
260	  const pass = (name, ok, detail) => {
261	    results.push({ name, ok });
262	    process.stdout.write(`case ${name}: ${ok ? 'PASS' : `FAIL ${detail || ''}`}\n`);
263	  };
264	  const run = (args, opts = {}) => spawnSync(process.execPath, [SELF, ...args],
265	    { encoding: 'utf8', timeout: 60_000, ...opts });
266	  const last = (r) => `${r.stdout || ''}`.trim().split('\n').pop() || '';
267	
268	  const HEADER = '| id | source | kind | tier | scope | anchor | teaches | status | opened | recheck | used-by |\n'
269	    + '|---|---|---|---|---|---|---|---|---|---|---|\n';
270	  const row = (id, url, scope) =>
271	    `| ${id} | title — ${url} | docs | B | ${scope} | §1 | t | mined | 2026-01-01 | 90d | p |\n`;
272	
273	  const mkdirp = (d) => { rmSync(d, { recursive: true, force: true }); mkdirSync(d, { recursive: true }); };
274	  const fixture = (dir, rows, known) => {
275	    mkdirp(dir);
276	    writeFileSync(join(dir, 'sources.md'), '## Registry\n' + HEADER + rows.join(''));
277	    writeFileSync(join(dir, 'reg.json'), JSON.stringify({ version: 1, known }, null, 2));
278	    return { reg: join(dir, 'reg.json'), src: join(dir, 'sources.md') };
279	  };
280	
281	  const baseRows = [
282	    row('S001', 'https://a.example/x', 's1'),
283	    row('S002', 'https://a.example/x', 's2'),   // dup group A (S001,S002)
284	    row('S003', 'https://b.example/y', 's3'),
285	    row('S004', 'https://c.example/z', 's4'),
286	    row('S005', 'https://c.example/z', 's4'),   // same url SAME scope — E04 family, not W04
287	  ];
288	  const baseKnown = [{ ids: ['S001', 'S002'], url: 'a.example/x', why: 'pre-rule duplicate, kept' }];
289	
290	  try {
291	    // case 1 — clean: one pinned group, same-scope same-url ignored. CLEAN groups=1 known=1
292	    {
293	      const d = join(root, 'd1'); const f = fixture(d, baseRows, baseKnown);
294	      const r = run(['--registry', f.reg, '--sources', f.src]);
295	      pass('clean', r.status === 0 && last(r) === 'SOURCE_DUPES: CLEAN groups=1 known=1',
296	        `exit=${r.status} last=${JSON.stringify(last(r))}`);
297	    }
298	    // case 2 — new duplicate: DRIFT new-duplicate, exit 1
299	    {
300	      const d = join(root, 'd2'); const f = fixture(d,
301	        [...baseRows, row('S006', 'https://d.example/w', 's5'), row('S007', 'https://d.example/w', 's6')],
302	        baseKnown);
303	      const r = run(['--registry', f.reg, '--sources', f.src]);
304	      pass('new-duplicate', r.status === 1 && last(r).includes('new-duplicate:d.example/w ids=S006,S007'),
305	        `exit=${r.status} last=${JSON.stringify(last(r))}`);
306	    }
307	    // case 3 — stale known: pinned group no longer duplicates. DRIFT stale-known
308	    {
309	      const d = join(root, 'd3'); const f = fixture(d,
310	        baseRows.map((r) => r.replace('s2', 's1')),  // S002 now shares S001's scope — no W04
311	        baseKnown);
312	      const r = run(['--registry', f.reg, '--sources', f.src]);
313	      pass('stale-known', r.status === 1 && last(r).includes('stale-known:S001,S002'),
314	        `exit=${r.status} last=${JSON.stringify(last(r))}`);
315	    }
316	    // case 4 — known ids shape wrong: pinned S001+S009 but live group is S001,S002. known-mismatch
317	    {
318	      const d = join(root, 'd4'); const f = fixture(d, baseRows,
319	        [{ ids: ['S001', 'S009'], url: 'a.example/x', why: 'wrong member' }]);
320	      const r = run(['--registry', f.reg, '--sources', f.src]);
321	      pass('known-mismatch', r.status === 1 && /known-mismatch:a\.example\/x/.test(last(r)),
322	        `exit=${r.status} last=${JSON.stringify(last(r))}`);
323	    }
324	    // case 5 — known url field wrong: same ids, different url → known-mismatch
325	    {
326	      const d = join(root, 'd5'); const f = fixture(d, baseRows,
327	        [{ ids: ['S001', 'S002'], url: 'zzz.example/x', why: 'wrong url' }]);
328	      const r = run(['--registry', f.reg, '--sources', f.src]);
329	      pass('known-url-mismatch', r.status === 1 && /known-mismatch|new-duplicate/.test(last(r)),
330	        `exit=${r.status} last=${JSON.stringify(last(r))}`);
331	    }
332	    // case 6 — empty known with a live group: DRIFT new-duplicate (never vacuous CLEAN)
333	    {
334	      const d = join(root, 'd6'); const f = fixture(d, baseRows, []);
335	      const r = run(['--registry', f.reg, '--sources', f.src]);
336	      pass('empty-known-live-dup', r.status === 1 && last(r).includes('new-duplicate:a.example/x'),
337	        `exit=${r.status} last=${JSON.stringify(last(r))}`);
338	    }
339	    // case 7 — empty known, no live group: CLEAN groups=0 known=0
340	    {
341	      const d = join(root, 'd7'); const f = fixture(d,
342	        [row('S001', 'https://a.example/x', 's1'), row('S003', 'https://b.example/y', 's3')], []);
343	      const r = run(['--registry', f.reg, '--sources', f.src]);
344	      pass('empty-clean', r.status === 0 && last(r) === 'SOURCE_DUPES: CLEAN groups=0 known=0',
345	        `exit=${r.status} last=${JSON.stringify(last(r))}`);
346	    }
347	    // case 8 — normalization parity: scheme/trailing-slash/case-equal urls group together
348	    {
349	      const d = join(root, 'd8'); const f = fixture(d,
350	        [row('S001', 'https://A.example/X/', 's1'), row('S002', 'http://a.example/X', 's2')],
351	        [{ ids: ['S001', 'S002'], url: 'a.example/X', why: 'normalized' }]);
352	      const r = run(['--registry', f.reg, '--sources', f.src]);
353	      pass('normalization', r.status === 0 && last(r) === 'SOURCE_DUPES: CLEAN groups=1 known=1',
354	        `exit=${r.status} last=${JSON.stringify(last(r))}`);
355	    }
356	    // case 9 — malformed JSON: FAIL-CLOSED exit 2
357	    {
358	      const d = join(root, 'd9'); const f = fixture(d, baseRows, baseKnown);
359	      writeFileSync(f.reg, '{ broken');
360	      const r = run(['--registry', f.reg, '--sources', f.src]);
361	      pass('registry-not-json', r.status === 2 && /FAIL-CLOSED reason=registry not valid JSON/.test(last(r)),
362	        `exit=${r.status} last=${JSON.stringify(last(r))}`);
363	    }
364	    // case 10 — version ≠ 1: FAIL-CLOSED exit 2
365	    {
366	      const d = join(root, 'd10'); const f = fixture(d, baseRows, baseKnown);
367	      writeFileSync(f.reg, JSON.stringify({ version: 2, known: baseKnown }));
368	      const r = run(['--registry', f.reg, '--sources', f.src]);
369	      pass('registry-version', r.status === 2 && /FAIL-CLOSED reason=registry version 2 !== 1/.test(last(r)),
370	        `exit=${r.status} last=${JSON.stringify(last(r))}`);
371	    }
372	    // case 11 — row id covered by two known entries: FAIL-CLOSED exit 2
373	    {
374	      const d = join(root, 'd11'); const f = fixture(d, baseRows, baseKnown);
375	      writeFileSync(f.reg, JSON.stringify({ version: 1, known: [...baseKnown, { ids: ['S001', 'S003'], url: 'x', why: 'overlap' }] }));
376	      const r = run(['--registry', f.reg, '--sources', f.src]);
377	      pass('known-overlap', r.status === 2 && /covered by two known entries/.test(last(r)),
378	        `exit=${r.status} last=${JSON.stringify(last(r))}`);
379	    }
380	    // case 12 — sources doc missing: FAIL-CLOSED exit 2
381	    {
382	      const d = join(root, 'd12'); const f = fixture(d, baseRows, baseKnown);
383	      rmSync(f.src);
384	      const r = run(['--registry', f.reg, '--sources', f.src]);
385	      pass('sources-absent', r.status === 2 && /FAIL-CLOSED/.test(last(r)),
386	        `exit=${r.status} last=${JSON.stringify(last(r))}`);
387	    }
388	  } finally {
389	    rmSync(root, { recursive: true, force: true });
390	  }
391	  const held = results.filter((r) => r.ok).length;
392	  process.stdout.write(`SOURCE_DUPES_SELFTEST: ${held === results.length ? 'PASS' : 'FAIL'} (${held}/${results.length})\n`);
393	  process.stdout.write(`VERDICT: ${held === results.length ? 'PASS' : 'FAIL'}\n`);
394	  process.exit(held === results.length ? 0 : 1);
395	}
396	
397	const argv = process.argv.slice(2);
398	if (argv.includes('--selftest')) {
399	  selftest();
400	} else {
401	  let reg = join(LANE, DEFAULT_REGISTRY);
402	  let src = join(LANE, DEFAULT_SOURCES);
403	  let explicitReg = false;
404	  for (let i = 0; i < argv.length; i++) {
405	    if (argv[i] === '--registry') {
406	      if (i + 1 >= argv.length) usage();
407	      reg = resolve(argv[++i]); explicitReg = true;
408	    } else if (argv[i] === '--sources') {
409	      if (i + 1 >= argv.length) usage();
410	      src = resolve(argv[++i]);
411	    } else {
412	      usage();
413	    }
414	  }
415	  if (explicitReg && !argv.includes('--sources')) {
416	    src = join(dirname(reg), 'sources.md');
417	  }
418	  emit(evaluate(reg, src));
419	}

